		t.Fatalf("results = %+v", resp.Results)
	}
	if resp.Results[0].ID != "A" || resp.Results[0].ResponseTime == nil ||
		*resp.Results[0].ResponseTime != wantA || resp.Results[0].DeadlineStatus != "met" {
