	var cycle []string
	var visit func(u string) bool
	visit = func(u string) bool {
		color[u] = gray
		path = append(path, u)
		for _, e := range adj[u] {
			switch color[e.to] {
			case gray:
				start := 0
				for i, id := range path {
					if id == e.to {
						start = i
						break
					}
				}
				cycle = append([]string(nil), path[start:]...)
				return true
			case white:
				if visit(e.to) {
					return true
				}
			}
		}
		path = path[:len(path)-1]
		color[u] = black
		return false
	}
	if visit(entry) {
		return cycle
	}
	return nil
}

// analyzeStacks evaluates every entrypoint in input order. An entry whose
// reachable graph contains a cycle is unbounded; otherwise the worst finite
// path cost (frames plus call overheads) decides within_limit vs exceeded.
// Ties between equal-cost paths resolve level by level toward the call that
// appears first in the calls array.
func analyzeStacks(graph stackGraph, entries []stackEntrypoint) stackResponse {
	// best[u] is the worst finite cost of any path starting at u; pick[u] is
	// the adjacency index of the first call achieving it (-1 for leaves).
	// Both are shared across entries: costs are entry-independent, and solve
	// only runs on nodes whose reachable subgraph is acyclic.
	best := make(map[string]int64, len(graph.frames))
	pick := make(map[string]int, len(graph.frames))
	var solve func(u string) int64
	solve = func(u string) int64 {
		if c, ok := best[u]; ok {
			return c
		}
		// The reachable subgraph is acyclic here, so a path visits each
		// function at most once: the total is bounded by
		// 4096*1e12 frames + 4095*1e12 overheads, far below int64 overflow.
		total := graph.frames[u]
		chosen := -1
		for i, e := range graph.adj[u] {
			cand := graph.frames[u] + e.overhead + solve(e.to)
			if chosen == -1 || cand > total {
				total = cand
				chosen = i
			}
		}
		best[u] = total
		pick[u] = chosen
		return total
	}

	resp := stackResponse{Safe: true, Analyzable: true, Results: make([]stackResult, 0, len(entries))}
	for _, ep := range entries {
		res := stackResult{
			Entry:      ep.entry,
			StackLimit: ep.stackLimit,
			WorstPath:  []string{},
			Cycle:      []string{},
		}
		if cycle := findStackCycle(ep.entry, graph.adj); cycle != nil {
			res.Status = "unbounded"
			res.Cycle = cycle
			resp.Safe = false
			resp.Analyzable = false
		} else {
			required := solve(ep.entry)
			path := []string{}
			for u := ep.entry; ; {
				path = append(path, u)
				c := pick[u]
				if c == -1 {
					break
				}
				u = graph.adj[u][c].to
			}
			res.RequiredBytes = &required
			res.WorstPath = path
			if required <= ep.stackLimit {
				res.Status = "within_limit"
			} else {
				res.Status = "exceeded"
				resp.Safe = false
			}
		}
		resp.Results = append(resp.Results, res)
	}
	return resp
}

// Package server exposes the frozen public surface of TickSafe.
//
// The baseline only reports process health. Later work adds the capabilities
// described in README.md; keep the exported surface here backward compatible.
package server

import (
	"encoding/json"
	"net/http"
)

// Version is the baseline release identifier.
const Version = "0.1.0"

type health struct {
	Status  string `json:"status"`
	Service string `json:"service"`
	Version string `json:"version"`
}

// Handler returns the HTTP surface served by the baseline.
func Handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			w.Header().Set("Allow", http.MethodGet)
			http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
			return
		}
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "ticksafe", Version: Version})
	})
	mux.HandleFunc(analyzePath, handleAnalyze)
	mux.HandleFunc(periodicAnalyzePath, handlePeriodicAnalyze)
	mux.HandleFunc(periodicSimulatePath, handlePeriodicSimulate)
	mux.HandleFunc(mutexAnalyzePath, handleMutexAnalyze)
	mux.HandleFunc(mailboxAnalyzePath, handleMailboxAnalyze)
	mux.HandleFunc(semaphoreAnalyzePath, handleSemaphoreAnalyze)
	mux.HandleFunc(interruptAnalyzePath, handleInterruptAnalyze)
	return mux
}

