		`{"functions":[{"id":"A","frameBytes":1}],"entrypoints":[{"entry":"A","stackLimit":10000000000000001}]}`,
		`{"functions":[{"id":"A","frameBytes":1}],"entrypoints":[{"entry":"A","stackLimit":1},{"entry":"A","stackLimit":2}]}`,
