func TestStackTooManyItems(t *testing.T) {
	// 4097 functions.
	var b strings.Builder
	b.WriteString(`{"functions":[`)
	for i := 0; i < 4097; i++ {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(`{"id":"f`)
		b.WriteString(strings.Repeat("x", 0))
		b.WriteString(strings.TrimSpace(strings.ReplaceAll(strings.Repeat(" ", 0), " ", "")))
		b.WriteString(jsonNumber(i))
		b.WriteString(`","frameBytes":0}`)
	}
	b.WriteString(`],"entrypoints":[{"entry":"f0","stackLimit":1}]}`)
	stacksError(t, postStacks(t, b.String(), "application/json"), http.StatusUnprocessableEntity, "validation_failed")

	// 257 calls.
	b.Reset()
	b.WriteString(`{"functions":[{"id":"a","frameBytes":0},{"id":"b","frameBytes":0}],"calls":[`)
	for i := 0; i < 257; i++ {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(`{"caller":"a","callee":"b","overheadBytes":0}`)
	}
	b.WriteString(`],"entrypoints":[{"entry":"a","stackLimit":1}]}`)
	stacksError(t, postStacks(t, b.String(), "application/json"), http.StatusUnprocessableEntity, "validation_failed")

	// 257 entrypoints.
	b.Reset()
	b.WriteString(`{"functions":[`)
	for i := 0; i < 257; i++ {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(`{"id":"f`)
		b.WriteString(jsonNumber(i))
		b.WriteString(`","frameBytes":0}`)
	}
	b.WriteString(`],"entrypoints":[`)
	for i := 0; i < 257; i++ {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(`{"entry":"f`)
		b.WriteString(jsonNumber(i))
		b.WriteString(`","stackLimit":1}`)
	}
	b.WriteString(`]}`)
	stacksError(t, postStacks(t, b.String(), "application/json"), http.StatusUnprocessableEntity, "validation_failed")
}

func jsonNumber(i int) string {
	return strings.TrimSpace(strings.ReplaceAll(strings.TrimSpace(strings.Repeat("", 0)), "", "")) + strconvItoa(i)
}

func strconvItoa(i int) string {
	if i == 0 {
		return "0"
	}
	var digits [8]byte
	pos := len(digits)
	for i > 0 {
		pos--
		digits[pos] = byte('0' + i%10)
		i /= 10
	}
	return string(digits[pos:])
}

